// Formats against the Swift reference (web/fixtures/golden, generated by `swift run vegolden`).
import { createHash } from 'node:crypto'
import { describe, expect, it } from 'vitest'
import { FormatError, latin1Decode } from '../src/lib/engine/binary'
import { DeviceConfiguration, RLE, SettingInfo, roundHalfEven } from '../src/lib/engine/deviceConfiguration'
import { AssistantLibrary } from '../src/lib/engine/assistantPackage'
import { GridPassword } from '../src/lib/engine/gridPassword'
import { SettingFile } from '../src/lib/engine/settingFile'
import * as names from '../src/lib/engine/settingNames'
import { bytes, golden, hasGolden, hasLibrary, hex, libraryPath, samplePath, samples } from './fixtures'

const sha = (b: Uint8Array) => createHash('sha256').update(b).digest('hex')

describe.runIf(hasGolden)('setting files match Swift', () => {
  for (const name of samples) {
    it(name, () => {
      const g = golden(`samples/${name}.json`)
      const input = bytes(samplePath(name))
      expect(sha(input)).toBe(g.sha256)
      const file = SettingFile.parse(input)
      expect(file.sections.map((s) => ({ name: s.name, length: s.body.length, sha256: sha(s.body) }))).toEqual(g.sections)
      expect(hex(file.encoded()) === hex(input)).toBe(g.roundTrip)

      const c = DeviceConfiguration.fromFile(file)
      expect(hex(c.encoded())).toBe(g.encoded)
      expect(c.formatVersion).toBe(g.formatVersion)
      expect(c.firmware.number).toBe(g.firmware.number)
      expect([c.firmware.family, c.firmware.type, c.firmware.version]).toEqual([g.firmware.family, g.firmware.type, g.firmware.version])

      const i = c.info
      expect({ version: i.version, firmware: i.firmware, configResponseChar: i.configResponseChar }).toEqual({
        version: g.info.version, firmware: g.info.firmware, configResponseChar: g.info.configResponseChar,
      })
      expect(i.records.map((r) => ({ scaleRaw: r.scaleRaw, offset: r.offset, defaultRaw: r.defaultRaw, minRaw: r.minRaw, maxRaw: r.maxRaw, step: r.step })))
        .toEqual(g.info.records)
      expect(hex(i.flagAttributes)).toBe(g.info.flagAttributes)
      expect(hex(i.settingAttributes)).toBe(g.info.settingAttributes)
      expect(i.gridTable ? hex(i.gridTable) : null).toBe(g.info.gridTable)

      const d = c.data
      expect(d.values).toEqual(g.data.values)
      expect(hex(d.assistantMemory)).toBe(g.data.assistantMemory)
      expect(d.serial ?? null).toBe(g.data.serial)
      expect(d.tokens.map(hex)).toEqual(g.data.tokens)
      expect(d.tokenTime).toBe(BigInt(g.data.tokenTime))
      expect(d.readTime).toBe(BigInt(g.data.readTime))
      for (const k of ['version', 'deviceID', 'firmwareAlt', 'obj20', 'obj21', 'byte8', 'firmware', 'configResponseChar'] as const)
        expect(d[k], k).toBe(g.data[k])
      expect(hex(d.firmwareExtra)).toBe(g.data.firmwareExtra)
      expect(hex(d.deviceRecord)).toBe(g.data.deviceRecord)

      for (const s of g.settings) {
        expect(c.raw(s.id)).toBe(s.raw)
        expect(c.value(s.id), `setting ${s.id}`).toBe(s.value)
        expect(names.settings[s.id] ?? '').toBe(s.name)
        expect(i.isHiddenSetting(s.id)).toBe(s.hidden)
        expect(i.isProtectedSetting(s.id)).toBe(s.protected)
      }
      for (const f of g.flags) {
        expect(names.flags[f.n]).toBe(f.name)
        expect(c.flag(f.n)).toBe(f.on)
        expect(c.supportsFlag(f.n)).toBe(f.supported)
        expect(i.isHiddenFlag(f.n)).toBe(f.hidden)
        expect(i.isProtectedFlag(f.n)).toBe(f.protected)
      }
    })
  }
})

describe.runIf(hasGolden && hasLibrary)('assistant library matches Swift', () => {
  it('packages, entries and latest', () => {
    const g = golden('library.json')
    const raw = bytes(libraryPath)
    expect(sha(raw)).toBe(g.sha256)
    const lib = AssistantLibrary.parse(raw)
    expect(lib.packages.map((p) => ({
      baseName: p.baseName, id: p.id, format: p.format, flags: p.flags, leading: hex(p.leading),
      entries: p.entries.map((e) => ({ name: e.name, dosTime: e.dosTime, attributes: e.attributes, length: e.bytes.length, sha256: sha(e.bytes) })),
    }))).toEqual(g.packages)
    expect(lib.latest.map((p) => p.baseName)).toEqual(g.latest)
  })
})

describe('format hardening', () => {
  it.runIf(hasGolden)('detects corruption', () => {
    const b = bytes(samplePath('s5'))
    b[200]! ^= 1
    expect(() => SettingFile.parse(b)).toThrow(/BareSettingInfo is corrupt/)
  })

  it('refuses a wrong magic and truncation', () => {
    expect(() => SettingFile.parse(new Uint8Array([1, 0, 0x41]))).toThrow(FormatError)
    const f = new SettingFile([{ name: 'A', body: new Uint8Array([1, 2, 3]) }]).encoded()
    expect(SettingFile.parse(f).sections[0]!.body).toEqual(new Uint8Array([1, 2, 3]))
    expect(() => SettingFile.parse(f.subarray(0, f.length - 1))).toThrow(FormatError)
  })

  it('refuses duplicate sections', () => {
    const f = new SettingFile([{ name: 'A', body: new Uint8Array([1]) }, { name: 'A', body: new Uint8Array([2]) }]).encoded()
    expect(() => SettingFile.parse(f)).toThrow(/more than once/)
  })

  it('RLE refuses a memory bomb and round-trips canonically', () => {
    const bomb = new Uint8Array([0, 0, 0xff, 0xff, 0xff])
    expect(() => RLE.decode(bomb)).toThrow(/larger than 4096/)
    const mem = new Uint8Array(4096).fill(0xff)
    mem.set([1, 2, 3, 3, 3, 3, 3, 3, 3, 9], 10)
    const enc = RLE.encode(mem, undefined)
    expect(RLE.decode(enc).memory).toEqual(mem)
  })

  it('rounds half to even and refuses non-finite values', () => {
    expect([0.5, 1.5, 2.5, -0.5, -1.5].map(roundHalfEven)).toEqual([0, 2, 2, 0, -2])
    const s = new SettingInfo(-100, 0, 0, 0, 6000)
    expect(s.rawValue(NaN)).toBeUndefined()
    expect(s.rawValue(Infinity)).toBeUndefined()
    expect(s.rawValue(12.345)).toBe(1234)
    expect(s.rawValue(1e9)).toBe(6000)
    expect(new SettingInfo(0, 0, 0, 0, 0).rawValue(1)).toBeUndefined()
  })

  it('grid password', () => {
    expect(GridPassword.verify('nope')).toBeUndefined()
    expect(GridPassword.verify('222222222222')).toBeUndefined()
    expect(latin1Decode(new Uint8Array([0xe9]))).toBe('é')
  })
})
